{
  "name": "IT8500系列直流电子负载",
  "name_en": "IT8500 Series DC Electronic Load",
  "manufacturer": "ITECH",
  "description": "IT8500系列是一类可编程直流电子负载，用于对电源、电池、适配器和直流变换器施加受控负载并测量电压、电流等参数。该设备支持恒流与恒压等工作方式，可用于电源性能测试、老化测试和实验室台式直流源评估。",
  "description_en": "The IT8500 Series is a programmable DC electronic load used to apply controlled loading to power supplies, batteries, adapters, and DC converters while measuring voltage and current. It supports operating modes such as constant current and constant voltage for power characterization, burn-in, and general laboratory evaluation of DC sources.",
  "tag_hints": [
    "programmable electronic load",
    "DC load testing",
    "constant current mode",
    "constant voltage mode",
    "power supply characterization",
    "battery discharge testing",
    "remote sense"
  ],
  "actions": [
    {
      "action_name": "auto-initialize",
      "description": "初始化电子负载，并切换到远程控制与恒流模式。",
      "description_en": "Initialize the electronic load and place it into remote-control and constant-current mode."
    },
    {
      "action_name": "auto-lock_front_panel",
      "description": "锁定或解锁前面板按键操作。",
      "description_en": "Lock or unlock the front-panel controls."
    },
    {
      "action_name": "auto-measure_current",
      "description": "测量负载输入电流。",
      "description_en": "Measure the load input current."
    },
    {
      "action_name": "auto-measure_voltage",
      "description": "测量负载输入电压。",
      "description_en": "Measure the load input voltage."
    },
    {
      "action_name": "auto-remote_sense",
      "description": "开启或关闭远端感测功能。",
      "description_en": "Enable or disable remote sensing."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置恒流模式下的电流设定值。",
      "description_en": "Set the current setpoint in constant-current mode."
    },
    {
      "action_name": "auto-set_cv_voltage",
      "description": "设置恒压模式下的电压设定值。",
      "description_en": "Set the voltage setpoint in constant-voltage mode."
    },
    {
      "action_name": "auto-set_mode_current",
      "description": "切换到恒流工作模式。",
      "description_en": "Switch to constant-current operating mode."
    },
    {
      "action_name": "auto-set_mode_voltage",
      "description": "切换到恒压工作模式。",
      "description_en": "Switch to constant-voltage operating mode."
    },
    {
      "action_name": "auto-toggle_output",
      "description": "打开或关闭负载输入。",
      "description_en": "Turn the load input on or off."
    }
  ]
}

